let mySize;
let seed = Math.random() * 2000;
let tile_count = 12;
let margin = 0;
let speed = 5;

// colors
let colors1 = "e3d7a3-f5989d-ea618e-fce4d6-caac71"
  .split("-")
  .map((a) => "#" + a);
let colors2 = "7d483e-b87644-e6d2c9-e45e00-905c40"
  .split("-")
  .map((a) => "#" + a);

let squares;

function setup() {
  pixelDensity(5);
  //mySize = 600;
  mySize = max(windowWidth, windowHeight);
  createCanvas(mySize, mySize);
  randomSeed(seed);
  background(245);
  mySetup();
}

function draw() {
  randomSeed(seed);
  background(245, 2.5);
  //scale(1.1);
  for (let w of waves) {
    //s.update();
    w.run();
  }
}

// easeIN and OUT 01 for roll
function easeOut(t) {
  return 1 - sq(t);
}

// easeIN and OUT 02 for move
function easeInOutSquare(t) {
  if ((t /= 0.5) < 1) {
    return 0.5 * sq(sq(t));
  } else {
    return 0.5 * ((t -= 2) * sq(t) + 2);
  }
}

// サイズを調整
function mySetup() {
  randomSeed(seed);
  mySize -= margin * 4;
  addWaves();
}

//
function addWaves() {
  waves = [];

  let w = mySize / tile_count;
  for (let i = 0; i < tile_count; i++) {
    for (let j = 0; j < tile_count; j++) {
      let x = i * w;
      let y = j * w;
      waves.push(new makeWave(x, y, w));
    }
  }
}

class makeWave {
  constructor(x, y, w) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.ang = (int(random(4)) * TAU) / 4;
    this.col = random(colors1);
    this.mv = 0;
    this.settime();
    this.pn = random() < 0.5 ? -1 : 1;
  }

  show() {
    push();
    translate(this.x + this.w / 2, this.y + this.w / 2);
    //scale(this.pn, 1);
    rotate(this.ang);
    translate(-this.w / 2, -this.w / 2);
    noFill();
    stroke(this.col);
    //line(0, 0, this.w, 0);
    let nn = int(this.w * 2);
    beginShape();
    for (let i = 0; i < nn; i++) {
      // y=Asin(bx−α)
      let theta = map(i, 0, nn - 1, -TAU * 2, TAU * 2);
      let sw = map(i, 0, nn - 1, -this.w * 2, this.w * 2);
      let verx = this.w / 2 - (this.w / 4) * sin(theta + this.mv);
      let very = this.w / 2 + i * 2 ;
      vertex(verx, very);
    }
    endShape();
    pop();
  }

  move() {
    if (0 <= this.t && this.t < this.t1) {
      let nrm = norm(this.t, 0, this.t1 - 1);
      this.mv = lerp(-TAU, TAU, easeOut(nrm));
    }
    if (this.t1 < this.t) {
      this.settime();
    }
    this.t++;
  }

  settime() {
    this.t = -int(random(map(speed, 1, 5, 3500, 100)));
    this.t1 = map(speed, 1, 5, 220, 60);
  }

  run() {
    this.show();
    this.move();
  }
}

function mouseClicked() {
  seed = Math.random() * 1000;
  randomSeed(seed);
  //background(245);
  loop();
}

function keyTyped() {
  if (key === "s" || key === "S") {
    noLoop();
    saveCanvas("MovingShapes-wave", "png");
  }
}

